import {dialog,type BrowserWindow} from 'electron';
import {writeFile,stat,unlink} from 'node:fs/promises';
import {join,dirname,basename} from 'node:path';
import {randomUUID} from 'node:crypto';
import {commitImageFile} from '../media-file';
/** Save only worker-generated bytes, bound to the still-open source window. */
export async function saveFormulaImage(window:BrowserWindow,format:'png'|'svg',data:Buffer,protect:(path:string)=>void,valid:()=>boolean){
  const choice=await dialog.showSaveDialog(window,{title:'导出公式',defaultPath:'One-formula.'+format,filters:[{name:format==='svg'?'SVG 矢量图':'PNG 图片',extensions:[format]}]});
  if(choice.canceled||!choice.filePath)return null;const destination=choice.filePath.toLowerCase().endsWith('.'+format)?choice.filePath:choice.filePath+'.'+format;protect(destination);if(!valid())throw Error('公式导出已取消');
  const previous=await stat(destination).catch(error=>{if(error.code!=='ENOENT')throw error;return undefined;}),stage=join(dirname(destination),'.one-formula-'+randomUUID()+'.part');
  try{
    await writeFile(stage,data,{flag:'wx',mode:0o600});if(!valid())throw Error('公式导出已取消');
    if(previous){const current=await stat(destination);if(current.ino!==previous.ino||current.size!==previous.size||current.mtimeMs!==previous.mtimeMs)throw Error('目标文件已改变，请重新导出');}
    await commitImageFile(stage,destination,!!previous);return basename(destination);
  }finally{await unlink(stage).catch(()=>{});}
}
